import numpy as np


def quantize_groups(w, group_size):
    w = np.asarray(w, dtype=float)
    if w.size % group_size:
        raise ValueError("length must be a multiple of group_size")
    blocks = w.reshape(-1, group_size)
    scale = np.abs(blocks).max(axis=1, keepdims=True) / 7
    scale = np.where(scale == 0, 1.0, scale)
    codes = np.clip(np.round(blocks / scale), -8, 7)
    return (codes * scale).reshape(w.shape)
